package com.cpf.starter.ftps;import java.time.Duration;import org.springframework.boot.context.properties.ConfigurationProperties;@ConfigurationProperties("cpf.integration.ftps") public class CpfFtpsProperties {private boolean enabled;private String host,username,password;private int port=21;private boolean implicit;private boolean verifyHostname=true;private long maxBytes=1073741824;private Duration timeout=Duration.ofSeconds(30);public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public String getHost(){return host;}public void setHost(String v){host=v;}public String getUsername(){return username;}public void setUsername(String v){username=v;}public String getPassword(){return password;}public void setPassword(String v){password=v;}public int getPort(){return port;}public void setPort(int v){port=v;}public boolean isImplicit(){return implicit;}public void setImplicit(boolean v){implicit=v;}public boolean isVerifyHostname(){return verifyHostname;}public void setVerifyHostname(boolean v){verifyHostname=v;}public long getMaxBytes(){return maxBytes;}public void setMaxBytes(long v){maxBytes=v;}public Duration getTimeout(){return timeout;}public void setTimeout(Duration v){timeout=v;}public void validate(){if(!enabled)return;if(host==null||username==null||password==null||port<1||!verifyHostname||maxBytes<1)throw new IllegalStateException("FTPS host/credentials/hostname verification/limits required");}}
